// === Tab: mySketch.js ===
/* Created for #WCCChallenge "Tunnel"


This sketch is based on two tutorials by Martijn Steinrucken (aka The Art of Code):
Twisted Toroid and star field tutorial
YouTube: youtube.com/TheArtOfCodeIsCool

*/

let gui, myShader;
let params = {
	a: 10.0,
	b: 30.0, 
	c: 3.0,
	zoom: 0.7,
	radius: 0.4
}

const colors = {
	//c1: [0.18, 0.027, 0.243, 0.5],
	c1: [0.02, 0.02, 0.02, 0.3]
}

async function setup() {
	let S = createVector(windowWidth, windowHeight);
	let canvas = createCanvas(S.x, S.y, WEBGL); // Thanks to Raphael for this trick!!
	canvas.position((windowWidth - width) / 2, (windowHeight - height) / 2);
	//createCanvas(windowWidth, windowHeight, WEBGL);
	pixelDensity(1);
	noStroke();

	const guiContainer = createDiv();
	guiContainer.id("gui");
	guiContainer.parent(document.body);

	gui = new lil.GUI({
		container: document.getElementById("gui"),
	});

	gui.add(params, "a", 0.0, 50.0, 1.0).name("No. of rings")
	gui.add(params, "b", 0.0, 50.0, 1.0).name("Amt of twist")
	gui.add(params, "c", 0.0, 50.0, 1.0).name("Number of ripples")
	gui.add(params, "zoom", 0.01, 0.7, 0.1).name("Level of zoom")
	gui.add(params, "radius", 0.05, 1.5, 0.1).name("Tunnel radius")
	gui.addColor(colors, "c1").name("Color of rings");

	gui.close()


	myShader = await createShader(vert, frag);
	//myShader = await createShader(resolveLygia(vert), resolveLygia(aya));
}

function draw() {
	shader(myShader);

	myShader.setUniform("u_resolution", [width, height]);
	myShader.setUniform("u_time", millis() / 1000);
	// myShader.setUniform("u_tex", img);
	myShader.setUniform("a", params.a);
	myShader.setUniform("b", params.b);
	myShader.setUniform("c", params.c);
	myShader.setUniform("zoom", params.zoom);
	myShader.setUniform("radius", params.radius);
	myShader.setUniform("c1", colors.c1);

	rect(0, 0, width, height);
}

const vert = `#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }`;

const frag = `#version 300 es
precision highp float;
out vec4 O;


// Pass in uniforms from the sketch.js file
uniform vec2 u_resolution; 
uniform float u_time;
uniform vec2 iMouse;
//uniform float iFrame;
uniform float a;
uniform float b;
uniform float c;
uniform float zoom;
uniform float radius;
uniform vec4 c1;

#define MAX_STEPS 100
#define MAX_DIST 100.
#define SURF_DIST .001
#define S smoothstep
#define NUM_LAYERS 4.
#define PI 3.14159

// #include "lygia/math/rotate2d.glsl"
// #include "lygia/sdf/torusSDF.glsl"
// #include "lygia/generative/worley.glsl"
// #include "lygia/space/sqTile.glsl"
// #include "lygia/math/const.glsl"

// This is from the Lygia library but is fairly standard
mat2 rotate2d(float r){
    float c = cos(r);
    float s = sin(r);
    return mat2(c, s, -s, c);
}

float random(vec2 co) {
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

float sdTorus( vec3 p, float radius){
  return length(vec2( length(p.xz) - 1., p.y) ) - radius;
}

float GetDist(vec3 p) {
    //float d = torusSDF(p, vec2(0.5), ra, rb);
    float d = sdTorus(p, 0.5);
    return d;
}

float RayMarch(vec3 ro, vec3 rd) {
	float dO=0.;

    for(int i=0; i<MAX_STEPS; i++) {
    	vec3 p = ro + rd*dO;
        float dS = GetDist(p);
        if(abs(dS)<SURF_DIST) break;
          dO += dS;
    }
    return dO;
}

vec3 GetNormal(vec3 p) {
	float d = GetDist(p);
    vec2 e = vec2(.001, 0);
    vec3 n = d - vec3(
        GetDist(p-e.xyy),
        GetDist(p-e.yxy),
        GetDist(p-e.yyx));

    return normalize(n);
}

vec3 GetRayDir(vec2 uv, vec3 pos, vec3 l, float z) {
    vec3 f = normalize(l-pos),  // forward vector
        r = normalize(cross(vec3(0,1,0), f)),  // right vector
        u = cross(f,r),  // up vector 
        c = pos + f*z,  // center of "virtual screen"
        i = c + uv.x*r + uv.y*u,  //intersection point camera ray and virtual screen
        rd = normalize(i-pos);  // ray direction
    return rd;
}

float Star(vec2 uv, float flare) {
     float d = length(uv);

    // Divide by d to get assymptotic falloff
    float m = .05/d;

    // Make star shape
    float rays = max(0., 1. - abs(uv.x*uv.y*1000.));
    m += rays*flare;
    uv *= rotate2d(PI/4.);
    rays = max(0., 1. - abs(uv.x*uv.y*1000.));
    m += rays*flare*.3;

    // Cut out glow is faded out to edge of box
    m *= S(1., .2, d);
    return m;
}

 vec3 StarLayer(vec2 uv)
 {
    vec3 col = vec3(0.);

    // Make boxes with (0,0) in middle
    vec2 gv = fract(uv) - 0.5;

    // Add Stars
    // Add id for boxes
    vec2 id = floor(uv);

		// https://github.com/patriciogonzalezvivo/lygia/blob/main/space/sqTile.glsl
		// vec4 t = sqTile(uv);
		// vec2 gv = t.xy - 0.5;
		// vec2 id = t.zw;

    // Iterate through neighborhood of box to add contribution from neighbors
    for (int  y =-1; y <= 1; y++)
    {
      for (int x=-1; x <= 1; x++) 
      {
         vec2 offset = vec2(x,y);
         float n = random(id+offset);

         //  Make stars different sizes
         float size = fract(n*345.678);
         // Add by .5 to keep values between -.5, .5
         float star = Star(gv - offset - vec2(n, fract(n*34.)) +.5, smoothstep(.9, 1., size)*.3);
         vec3 color = sin(vec3(.2, .3, .9)*fract(n*2345.2)*19.)*.5+.5;
         color += color*vec3(.5, .01, 1.+size); // can filter out color by changing R/G/B value to 0.

        // Add a twinkle
        star *= -sin(u_time*3.+n*2.0*PI)*.5 + 1.;

        col += star*size*color;
      }
    }
    return col;
}

void main()
{
    vec2 uv = (gl_FragCoord.xy - .5*u_resolution.xy)/u_resolution.y;
	 vec2 m = iMouse.xy/u_resolution.xy;
    float t = u_time*.1;
    uv *= rotate2d(t);  // add rotation

    // change z to -1 to get inside torus
    vec3 ro = vec3(0, 0, -1.0);  // camera origin

    // change the look at point so that it goes left and right
	vec3 lookat = mix(vec3(0), vec3(-0.8, 0, -0.8), sin(t*1.56)*.5+.5);


    //zoom in and out
	float zoom = mix(.2, zoom, sin(t)*.5 + .5);

    vec3 rd = GetRayDir(uv, ro, lookat, zoom);
   // float radius = mix(.3, 1.5, sin(t*.4)*.5 + .5);; // original
	float radius = mix(0.3, radius, sin(t*.4)*.5 + .5);;
    float dS, dO;
    vec3 p;

    for(int i=0; i<MAX_STEPS; i++) {
    	  p = ro + rd*dO;
        // add - to get inside torus
        dS = -(length(vec2( length(p.xz) - 1., p.y) ) - radius); // original

        if(dS<SURF_DIST) break; // did we hit anything?
          dO += dS;
    }

    vec4 col = vec4(vec3(0.0), 1.0);

  for (float i=0.; i<1.; i += 1./NUM_LAYERS)
    {
        // Depth increases with time; if hits 1 get reset
        float depth = fract(i+t);
        float scale = mix(0.5, 10.0, depth);
		 //float scale = mix(20., .5, depth);
        // Adjust so that repeat is not noticable
        float fade = depth*S(1., .9, depth);  // multiply by depth 0 in back
        col.rgb += StarLayer(uv*scale+i*453.)*fade; // add value so layers are shifted
    }
    //vec3 imgCol = texture(img, uv).rgb;

    if (dS<SURF_DIST) {
       //float x = 0.5 *( atan(p.x, p.z)  + t*.5);  
	    // y term adds rings around torus
       // x term creates twists around torus
	    float x = atan(p.x, p.z)  + t*.5; // -pi to pi
	    float y = atan( length(p.xz)-1.0, p.y );

       // Add spirals around torus
       float bands = sin(y*a + x*b); // coefficients need to be whole number 
       float ripples = sin((x*a - y*b)*c) *.5 + .5;
       //  float bands = sin(y*10. + x*30.); // coefficients need to be whole number 
       // float ripples = sin((x*10. - y*30.)*20.) *.5 + .5;
       //coefficients need to stay in same ratio
       //float waves = sin(x*2. - y*6. + t*20.); // can change direction of waves by changing sign of y
	    float waves = sin(x*2. - y*2.0*(b/a) + t*20.);
       // make bands crisper
       float b1 = S(-.2, .2, bands);
       float b2 = S(-.2, .2, bands - .5);

       float m = b1*(1.-b2);  // only show edges to add grooves

       // only show ripples inside of grooves
       // use max so that uvs don't go negative
       m = max(m, ripples*b2*max(0., waves));
       m += max(0., waves* .3 * b2);

       // mix m and its inverse, use smoothstep to transition smoothly

       float c = mix ( m , 1.-m, S( -.3, .3, sin(x*2.+t) ) ) ;

      col = mix(col, c1, c);

    }
	O = col;

}`

